+/** Theoretical (from sales) vs actual (consume movements) use per item between two days, inclusive. */
+export function varianceReport(store, from, to) {
+  const inDays = (instant) => {
+    const day = instant.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  const actual = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inDays(s.soldAt)) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    if (!dish) continue;
+    for (const n of scaled(getRecipe(store, dish.recipeId), s.qty))
+      theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inDays(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return [...new Set([...theoretical.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round(theoretical.get(itemId) ?? 0);
+      const a = round(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
